          return parseFloat(item.multiple_pricing['DELIVERY']);
        }
        if (item.sale_price_2) return parseFloat(item.sale_price_2);
        return parseFloat(item.price || 0);
      case 4: // Quick Bill
        if (item.sale_price_3) return parseFloat(item.sale_price_3);
        return parseFloat(item.price || 0);
      default: // 1 = Dine-In
        if (item.multiple_pricing && item.multiple_pricing['DINE_IN'] !== undefined && item.multiple_pricing['DINE_IN'] !== null) {
          return parseFloat(item.multiple_pricing['DINE_IN']);
        }
